console.log('[' + new Date().toISOString() + '] Policy Loader - START');

const sd = $getWorkflowStaticData('global');

sd.scenarios = sd.scenarios || {
  "winter_emergency_surge": {
    "description": "Cold snap causes HVAC failures",
    "event_count": 50,
    "time_spread_minutes": 120,
    "event_distribution": {
      "emergency": 0.60,
      "inquiry": 0.25,
      "appointment": 0.10,
      "complaint": 0.05
    },
    "urgency_bias": "high",
    "time_pattern": "evening_heavy",
    "customer_pool": [1, 2, 3, 4],
    "revenue_range": [250, 600]
  },
  "routine_maintenance_day": {
    "description": "Normal business day",
    "event_count": 30,
    "time_spread_minutes": 480,
    "event_distribution": {
      "appointment": 0.50,
      "inquiry": 0.25,
      "follow_up": 0.15,
      "maintenance": 0.10
    },
    "urgency_bias": "low",
    "time_pattern": "business_hours",
    "customer_pool": [1, 2, 3, 4, 5],
    "revenue_range": [150, 350]
  },
  "summer_heatwave": {
    "description": "AC failures during heat emergency",
    "event_count": 75,
    "time_spread_minutes": 180,
    "event_distribution": {
      "emergency": 0.70,
      "inquiry": 0.20,
      "complaint": 0.10
    },
    "urgency_bias": "extreme",
    "time_pattern": "afternoon_spike",
    "customer_pool": [1, 2, 5],
    "revenue_range": [300, 800]
  }
};

const scenarioName = $input.first().json.scenario_name || 'routine_maintenance_day';
const scenario = sd.scenarios[scenarioName];

if (!scenario) {
  throw new Error(`Unknown scenario: ${scenarioName}. Available: ${Object.keys(sd.scenarios).join(', ')}`);
}

const eventCount = $input.first().json.event_count || scenario.event_count;
const timeSpread = $input.first().json.time_spread_minutes || scenario.time_spread_minutes;

const output = {
  scenario: {
    ...scenario,
    event_count: eventCount,
    time_spread_minutes: timeSpread
  },
  scenario_name: scenarioName,
  policy: {
    idempotency_enabled: true,
    idempotency_ttl_minutes: 5,
    enable_jitter: true,
    jitter_minutes: 5
  }
};

console.log('[' + new Date().toISOString() + '] Policy Loader - Loaded scenario:', scenarioName);
return output;

console.log('[' + new Date().toISOString() + '] State Initializer - START');

function generateRunId() {
  const prefix = 'GEN';
  const random = Math.random().toString(36).substring(2, 9).toUpperCase();
  const timestamp = Date.now().toString(36).toUpperCase();
  return `${prefix}-${random}-${timestamp}`;
}

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const scenario = $input.first().json.scenario;
const scenarioName = $input.first().json.scenario_name;
const policy = $input.first().json.policy;

const sd = $getWorkflowStaticData('global');
sd._event_cache = sd._event_cache || {};

const now = Date.now();
for (const key in sd._event_cache) {
  if (sd._event_cache[key].expires_at < now) {
    delete sd._event_cache[key];
  }
}

const state = {
  run_id: generateRunId(),
  workflow_sequence_id: generateUUID(),
  scenario_name: scenarioName,
  goal: `Generate ${scenario.event_count} events for ${scenarioName}`,
  constraints: {
    max_events: scenario.event_count,
    time_spread_minutes: scenario.time_spread_minutes,
    respect_patterns: true
  },
  counters: {
    events_created: 0,
    events_deduped: 0,
    errors: 0,
    current_step: 0,
    start_time: Date.now()
  },
  scratchpad: {
    plan: `Create ${scenario.event_count} events following ${scenario.time_pattern} pattern`,
    progress: "Initializing...",
    observations: []
  },
  scenario: scenario,
  policy: policy
};

console.log('[' + new Date().toISOString() + '] State Initializer - Created state with run_id:', state.run_id);
return state;

console.log('[' + new Date().toISOString() + '] Generator Logic - START Step:', $input.first().json.counters.current_step);

const state = $input.first().json;
const scenario = state.scenario;
const counters = state.counters;

function actionId() {
  return Date.now().toString(36).toUpperCase() + 
         Math.random().toString(36).substring(2, 10).toUpperCase();
}

function selectEventType(distribution) {
  const rand = Math.random();
  let cumulative = 0;

  for (const [eventType, probability] of Object.entries(distribution)) {
    cumulative += probability;
    if (rand <= cumulative) return eventType;
  }

  return "inquiry";
}

function calculateUrgency(eventType, urgencyBias) {
  const baseUrgency = {
    "emergency": [8, 9, 10],
    "complaint": [5, 6, 7],
    "inquiry": [3, 4, 5],
    "appointment": [2, 3, 4],
    "follow_up": [1, 2, 3],
    "maintenance": [2, 3, 4]
  };

  let range = baseUrgency[eventType] || [3, 4, 5];

  if (urgencyBias === "high") {
    range = range.slice(-2);
  } else if (urgencyBias === "extreme") {
    range = [Math.max(...range)];
  }

  return range[Math.floor(Math.random() * range.length)];
}

function calculateTimestamp(scenario, eventIndex, totalEvents) {
  const startTime = counters.start_time;
  const spreadMs = scenario.time_spread_minutes * 60 * 1000;

  let baseOffset = (spreadMs / totalEvents) * eventIndex;

  if (scenario.time_pattern === "evening_heavy") {
    const threshold = totalEvents * 0.7;
    if (eventIndex > threshold) {
      baseOffset = spreadMs * 0.7 + 
                   (eventIndex - threshold) * (spreadMs * 0.3) / (totalEvents * 0.3);
    }
  } else if (scenario.time_pattern === "afternoon_spike") {
    const midStart = totalEvents * 0.3;
    const midEnd = totalEvents * 0.7;
    if (eventIndex > midStart && eventIndex < midEnd) {
      baseOffset = spreadMs * 0.3 + 
                   (eventIndex - midStart) * (spreadMs * 0.4) / (midEnd - midStart);
    }
  }

  const jitter = state.policy.enable_jitter ? 
    (Math.random() - 0.5) * (state.policy.jitter_minutes * 60 * 1000) : 0;

  return new Date(startTime + baseOffset + jitter).toISOString();
}

function calculateRevenue(eventType, revenueRange) {
  const [min, max] = revenueRange;
  const base = min + Math.random() * (max - min);

  const multipliers = {
    "emergency": 1.5,
    "complaint": 1.0,
    "inquiry": 0.8,
    "appointment": 1.2,
    "follow_up": 0.5,
    "maintenance": 1.0
  };

  return Math.round(base * (multipliers[eventType] || 1.0));
}

function generateDescription(eventType) {
  const templates = {
    "emergency": ["No heat - urgent!", "AC failure - 90° inside", "System down - immediate help"],
    "complaint": ["Service was delayed", "Technician was rude", "Not satisfied with repair"],
    "inquiry": ["Question about maintenance", "Need quote for install", "When is next service?"],
    "appointment": ["Schedule spring tune-up", "Book filter replacement", "Annual inspection due"],
    "follow_up": ["Following up on estimate", "Checking repair status", "Question about invoice"],
    "maintenance": ["Routine 6-month check", "Filter change needed", "System inspection"]
  };

  const options = templates[eventType] || ["Customer contact"];
  return options[Math.floor(Math.random() * options.length)];
}

const eventType = selectEventType(scenario.event_distribution);
const customerId = scenario.customer_pool[Math.floor(Math.random() * scenario.customer_pool.length)];
const urgency = calculateUrgency(eventType, scenario.urgency_bias);
const timestamp = calculateTimestamp(scenario, counters.events_created, scenario.event_count);
const revenue = calculateRevenue(eventType, scenario.revenue_range);
const description = generateDescription(eventType);

const output = {
  state: state,
  next_action: {
    type: "create_event",
    action_id: actionId(),
    event_data: {
      event_type: eventType,
      event_timestamp: timestamp,
      customer_id: customerId,
      urgency: urgency,
      description: description,
      estimated_revenue: revenue,
      event_payload: {
        source: "event_generator",
        scenario: state.scenario_name,
        run_id: state.run_id
      },
      is_manual_trigger: false,
      scenario_name: state.scenario_name
    }
  },
  state_update: {
    confidence: Math.random() * 0.3 + 0.7,
    reasoning: `Generated ${eventType} event based on ${scenario.urgency_bias} urgency scenario`
  }
};

console.log('[' + new Date().toISOString() + '] Generator Logic - Generated:', eventType, 'urgency:', urgency);
return output;

console.log('[' + new Date().toISOString() + '] Validator - START');

const item = $input.first().json;
const eventData = item.next_action.event_data;

const required = ['event_type', 'event_timestamp', 'customer_id', 'urgency', 'description'];
for (const field of required) {
  if (!eventData[field]) {
    throw new Error(`Missing required field: ${field}`);
  }
}

if (eventData.urgency < 1 || eventData.urgency > 10) {
  throw new Error(`Invalid urgency: ${eventData.urgency}. Must be 1-10`);
}

if (eventData.estimated_revenue < 0) {
  throw new Error(`Invalid revenue: ${eventData.estimated_revenue}`);
}

console.log('[' + new Date().toISOString() + '] Validator - PASSED');
return item;

console.log('[' + new Date().toISOString() + '] Idempotency Gate - START');

const output = $input.first().json;
const eventData = output.next_action.event_data;
const policy = output.state.policy;

if (!policy.idempotency_enabled) {
  console.log('[' + new Date().toISOString() + '] Idempotency Gate - DISABLED, passing through');
  return { ...output, deduped: false };
}

const keyParts = [
  output.state.scenario_name,
  eventData.event_type,
  eventData.customer_id,
  eventData.event_timestamp.substring(0, 16)
];
const idempotencyKey = keyParts.join('::');

const sd = $getWorkflowStaticData('global');
const now = Date.now();
const ttlMs = policy.idempotency_ttl_minutes * 60 * 1000;

const cached = sd._event_cache[idempotencyKey];
if (cached && cached.expires_at > now) {
  console.log('[' + new Date().toISOString() + '] Idempotency Gate - CACHE HIT:', idempotencyKey);
  return {
    ...output,
    deduped: true,
    cached_event_id: cached.event_id,
    cache_hit_at: new Date().toISOString()
  };
}

sd._event_cache[idempotencyKey] = {
  created_at: now,
  expires_at: now + ttlMs,
  event_id: null
};

console.log('[' + new Date().toISOString() + '] Idempotency Gate - CACHE MISS, creating new event');
return {
  ...output,
  deduped: false,
  idempotency_key: idempotencyKey,
  cache_miss_at: new Date().toISOString()
};

console.log('[' + new Date().toISOString() + '] Cache Hit Logger - Event was deduplicated');

const item = $input.first().json;

return {
  run_id: item.state.run_id,
  workflow_sequence_id: item.state.workflow_sequence_id,
  action: "cache_hit",
  idempotency_key: item.idempotency_key,
  cached_event_id: item.cached_event_id,
  scenario_name: item.state.scenario_name,
  event_type: item.next_action.event_data.event_type,
  timestamp: new Date().toISOString(),
  message: "Event creation skipped (idempotency cache hit)"
};

console.log('[' + new Date().toISOString() + '] UUID Generator - Creating execution ID');

const crypto = require('crypto');

return {
  execution_id: crypto.randomUUID(),
  workflow_name: 'event_generator',
  event_id: $('PostgreSQL Insert Event').item.json.event_id,
  started_at: new Date().toISOString(),
  completed_at: new Date().toISOString(),
  status: 'success',
  duration_ms: 0
};

console.log('[' + new Date().toISOString() + '] Counter Updater - START');

const output = $input.all()[0].json;
const eventId = $('PostgreSQL Insert Event').item.json.event_id;
const deduped = output.deduped || false;

const state = JSON.parse(JSON.stringify(output.state));

state.counters.current_step += 1;

if (deduped) {
  state.counters.events_deduped += 1;
} else {
  state.counters.events_created += 1;

  const sd = $getWorkflowStaticData('global');
  if (sd._event_cache && sd._event_cache[output.idempotency_key]) {
    sd._event_cache[output.idempotency_key].event_id = eventId;
  }
}

const created = state.counters.events_created;
const total = state.scenario.event_count;
const pct = Math.round((created / total) * 100);

state.scratchpad.progress = `Created ${created}/${total} events (${pct}%)`;
state.scratchpad.observations.push(
  deduped ? 
    `Step ${state.counters.current_step}: Deduped ${output.next_action.event_data.event_type}` :
    `Step ${state.counters.current_step}: Created ${output.next_action.event_data.event_type} (ID: ${eventId})`
);

if (state.scratchpad.observations.length > 5) {
  state.scratchpad.observations = state.scratchpad.observations.slice(-5);
}

console.log('[' + new Date().toISOString() + '] Counter Updater - Progress:', pct + '%');
return state;

console.log('[' + new Date().toISOString() + '] Success Response - Generating final output');

const state = $input.first().json;

const durationMs = Date.now() - state.counters.start_time;
const durationSec = (durationMs / 1000).toFixed(2);

const output = {
  status: "success",
  run_id: state.run_id,
  workflow_sequence_id: state.workflow_sequence_id,
  scenario_name: state.scenario_name,
  summary: {
    events_created: state.counters.events_created,
    events_deduped: state.counters.events_deduped,
    total_steps: state.counters.current_step,
    errors: state.counters.errors,
    duration_seconds: parseFloat(durationSec),
    events_per_second: (state.counters.events_created / parseFloat(durationSec)).toFixed(2)
  },
  scenario: {
    description: state.scenario.description,
    event_count: state.scenario.event_count,
    time_spread_minutes: state.scenario.time_spread_minutes,
    pattern: state.scenario.time_pattern
  },
  observations: state.scratchpad.observations,
  message: `Successfully generated ${state.counters.events_created} events in ${durationSec}s`,
  timestamp: new Date().toISOString()
};

console.log('[' + new Date().toISOString() + '] Success Response - COMPLETE:', output.summary);
return output;

console.log('[' + new Date().toISOString() + '] Error Handler - Handling error');

const error = $input.first().json.error || $input.first().error || {};
const state = $input.first().json.state || {};

return {
  status: "error",
  run_id: state.run_id || "unknown",
  scenario_name: state.scenario_name || "unknown",
  error: {
    message: error.message || "Unknown error",
    type: error.name || "Error",
    timestamp: new Date().toISOString()
  },
  summary: {
    events_created: state.counters?.events_created || 0,
    events_deduped: state.counters?.events_deduped || 0,
    total_steps: state.counters?.current_step || 0
  },
  message: "Event generation failed - see error details"
};
